// S2 – Étape 0 : lire un uplink ChirpStack v4 (LoRaWAN privé) et le mettre au même format
// que le récepteur point à point, pour que la suite du flux (étapes 1 et 2) soit commune.
// Entrée : message JSON publié par ChirpStack sur application/<id>/device/<devEui>/event/up
//   { deduplicationId, time, deviceInfo { devEui, deviceName }, fPort, fCnt, data (base64),
//     object (si le codec est installé dans ChirpStack), rxInfo [ { rssi, snr, gwTime, nsTime, … } ] }
// Sortie : { received_at, payload_hex, rssi, snr, source, dev_eui, fcnt } vers « 1. Décoder ».
// La trame est toujours décodée ici par le codec S1, même si ChirpStack a déjà rempli « object » :
// un seul décodage, le même pour les deux voies.
const up = msg.payload || {};
const rx = Array.isArray(up.rxInfo) ? up.rxInfo : [];
// ChirpStack a déjà supprimé les réceptions en double (plusieurs passerelles) : rxInfo les liste.
// On garde la meilleure réception (RSSI le plus fort).
const meilleure = rx.reduce((m, r) => (m === null || (r.rssi ?? -999) > (m.rssi ?? -999) ? r : m), null) || {};

// Règle 4 du contrat : horodatage à la réception. On prend l'heure de la passerelle si elle
// est connue (time, ou gwTime de la réception), sinon l'heure du serveur ChirpStack (nsTime),
// sinon l'heure de Node-RED.
const recuA = up.time || meilleure.gwTime || meilleure.nsTime || new Date().toISOString();

let hex = null;
if (typeof up.data === "string" && up.data.length) {
    hex = Buffer.from(up.data, "base64").toString("hex").toUpperCase();
}
const devEui = (up.deviceInfo && up.deviceInfo.devEui) || null;

msg.payload = {
    received_at: recuA,
    payload_hex: hex,            // null si l'uplink n'a pas de données : « 1. Décoder » le rejettera
    rssi: meilleure.rssi ?? null,
    snr: meilleure.snr ?? null,
    source: "chirpstack",
    dev_eui: devEui,
    fcnt: up.fCnt ?? null
};
node.status({ fill: hex ? "green" : "yellow", shape: "dot",
              text: (devEui || "appareil inconnu") + (up.fCnt !== undefined ? " · fCnt " + up.fCnt : "") });
return msg;

// S2 – Étape 1 : décoder la trame brute et produire une mesure normalisée.
// Entrée : message du récepteur (ou de l'injecteur) sur pce92/uplink, ou uplink ChirpStack
// déjà remis à ce format par « 0. Lire ChirpStack » :
//   { received_at, payload_hex, rssi, snr, source }
// Sortie 1 : mesure normalisée. Sortie 2 : trame rejetée.
const codec = global.get("codec");
if (!codec) {
    node.error("Codec S1 non chargé : ajouter codec dans functionGlobalContext (voir plateforme/flows/README.md)");
    node.status({ fill: "red", shape: "ring", text: "codec absent" });
    return null;
}

const entree = msg.payload || {};
const recuA = entree.received_at || new Date().toISOString(); // règle 4 : horodatage à la réception

function rejet(raison) {
    node.warn("Trame rejetée : " + raison);
    return [null, {
        topic: "pce92/evenements",
        payload: { type: "rejet", raison: raison, received_at: recuA,
                   payload_hex: entree.payload_hex || null, source: entree.source || null }
    }];
}

if (typeof entree.payload_hex !== "string") {
    return rejet("message sans payload_hex");
}
const hex = entree.payload_hex.replace(/\s+/g, "");
if (!/^[0-9a-fA-F]*$/.test(hex) || hex.length % 2 !== 0) {
    return rejet("payload_hex n'est pas de l'hexadécimal valide");
}

const octets = hex.match(/../g).map(h => parseInt(h, 16));
const res = codec.decodeUplink({ bytes: octets });
if (res.errors) {
    return rejet(res.errors.join(" ; "));
}

const d = res.data;
msg.topic = "pce92/mesures/" + d.node_id;
msg.payload = {
    node_id: d.node_id,
    received_at: recuA,
    water_mm: d.water_valid ? d.water_mm : null,  // null = mesure invalide (0xFFFF)
    water_valid: d.water_valid,
    batt_v: d.batt_v,                             // null = tension inconnue (0xFF)
    seq: d.seq,
    alert: d.alert,
    next_min: d.next_min,                         // null = inconnu (0xFF)
    expected_next_at: d.next_min === null ? null
        : new Date(Date.parse(recuA) + d.next_min * 60000).toISOString(),
    rssi: entree.rssi ?? null,
    snr: entree.snr ?? null,
    source: entree.source ?? null,
    payload_hex: hex.toUpperCase(),
    warnings: res.warnings
};
if (res.warnings.length) {
    node.warn("Nœud " + d.node_id + ", seq " + d.seq + " : " + res.warnings.join(" ; "));
}
node.status({ fill: d.alert ? "red" : "green", shape: "dot",
              text: "nœud " + d.node_id + " · seq " + d.seq + " · " + (d.water_valid ? d.water_mm + " mm" : "invalide") });
return [msg, null];

// S2 – Étape 2 : contrôler le compteur seq (règle 5 du contrat).
// Écart = (seq - dernier seq) modulo 65536, par nœud :
//   = 1          : trame normale ;
//   > 1          : trames perdues (la mesure est gardée) ;
//   = 0          : doublon (écarté) ;
//   > 32768      : la trame est plus ancienne que la dernière reçue. Trois cas :
//     - seq déjà reçu, trame identique        -> doublon en retard (écarté) ;
//     - seq compté comme perdu                 -> trame reçue en retard : elle n'est pas
//       publiée comme mesure actuelle (son heure de mesure est inconnue en v1.2 :
//       annexe A, une ancienne mesure ne doit pas déclencher d'alerte nouvelle). Elle est
//       gardée dans le journal des événements, et retirée du compte des pertes ;
//     - sinon                                   -> retour en arrière du compteur
//       (redémarrage du nœud) : la mesure est gardée, la mémoire du nœud repart de zéro.
// Mémoire par nœud : le dernier seq, les MEMOIRE derniers seq reçus (avec leur trame)
// et les seq perdus récents. Elle repart de zéro au redémarrage de Node-RED.
// Sortie 1 : mesure acceptée. Sortie 2 : événement.
const MEMOIRE = 64;
const m = msg.payload;
const cle = "seq_" + m.node_id;
const etat = flow.get(cle);
const precedent = etat ? etat.dernier : undefined;
const ecart = etat ? (m.seq - precedent + 65536) % 65536 : null;

function evenement(type, details) {
    return {
        topic: "pce92/evenements",
        payload: Object.assign({ type: type, node_id: m.node_id, seq: m.seq, received_at: m.received_at }, details)
    };
}

// Garde la trame reçue en mémoire (les MEMOIRE plus récentes).
function retenir(e) {
    e.recus[m.seq] = m.payload_hex;
    e.ordre.push(m.seq);
    while (e.ordre.length > MEMOIRE) delete e.recus[e.ordre.shift()];
}

// 1. Première trame de ce nœud depuis le démarrage de Node-RED : pas de contrôle possible.
if (!etat) {
    const e = { dernier: m.seq, dernier_recu_a: m.received_at, next_min: m.next_min, recus: {}, ordre: [], perdus: [] };
    retenir(e);
    flow.set(cle, e);
    m.seq_gap = null;
    m.lost_before = 0;
    node.status({ fill: "green", shape: "dot", text: "nœud " + m.node_id + " · seq " + m.seq });
    return [msg, null];
}

// 2. Doublon immédiat (même seq que la dernière trame).
if (ecart === 0) {
    node.status({ fill: "yellow", shape: "ring", text: "doublon écarté · nœud " + m.node_id + " · seq " + m.seq });
    return [null, evenement("doublon", { en_retard: false })];
}

// 3. Trame plus ancienne que la dernière reçue.
if (ecart > 32768) {
    const retard = (precedent - m.seq + 65536) % 65536;   // en nombre de trames
    if (etat.recus[m.seq] !== undefined && etat.recus[m.seq] === m.payload_hex) {
        node.status({ fill: "yellow", shape: "ring", text: "doublon en retard écarté · nœud " + m.node_id + " · seq " + m.seq });
        return [null, evenement("doublon", { en_retard: true, retard_trames: retard })];
    }
    const i = etat.perdus.indexOf(m.seq);
    if (i >= 0) {
        etat.perdus.splice(i, 1);
        retenir(etat);
        flow.set(cle, etat);
        // Heure de mesure estimée : le contrat v1.2 ne la transmet pas. On la reconstruit à partir
        // de la dernière trame reçue et de la période (next_min), comme le propose l'annexe A.
        const periode = (etat.next_min || m.next_min || 30) * 60000;
        const estimee = new Date(Date.parse(etat.dernier_recu_a) - retard * periode).toISOString();
        node.status({ fill: "blue", shape: "ring", text: "trame en retard · nœud " + m.node_id + " · seq " + m.seq });
        return [null, evenement("trame_en_retard", {
            retard_trames: retard, mesure_estimee_a: estimee,
            water_mm: m.water_mm, water_valid: m.water_valid, batt_v: m.batt_v, alert: m.alert
        })];
    }
    // Redémarrage du nœud : la mémoire repart de cette trame.
    const e = { dernier: m.seq, dernier_recu_a: m.received_at, next_min: m.next_min, recus: {}, ordre: [], perdus: [] };
    retenir(e);
    flow.set(cle, e);
    m.seq_gap = ecart;
    m.lost_before = 0;
    node.status({ fill: "yellow", shape: "dot", text: "compteur revenu en arrière · nœud " + m.node_id + " · seq " + m.seq });
    return [msg, evenement("retour_seq", { seq_precedent: precedent })];
}

// 4. Trame normale (écart 1) ou trames perdues juste avant (écart > 1).
let evt = null;
m.seq_gap = ecart;
m.lost_before = ecart - 1;
if (m.lost_before > 0) {
    evt = evenement("trames_perdues", { nombre: m.lost_before, seq_precedent: precedent });
    for (let k = 1; k <= m.lost_before; k++) etat.perdus.push((precedent + k) % 65536);
    // On ne garde que les pertes récentes (au plus MEMOIRE trames derrière la dernière).
    etat.perdus = etat.perdus.filter(s => (m.seq - s + 65536) % 65536 <= MEMOIRE);
}
etat.dernier = m.seq;
etat.dernier_recu_a = m.received_at;
etat.next_min = m.next_min;
retenir(etat);
flow.set(cle, etat);
node.status({ fill: m.lost_before ? "yellow" : "green", shape: "dot",
              text: "nœud " + m.node_id + " · seq " + m.seq + (m.lost_before ? " · " + m.lost_before + " perdue(s)" : "") });
return [msg, evt];

// Événements des 7 derniers jours (pour les compteurs et la liste de la vue technique).
msg.params = { $depuis: new Date(Date.now() - 7 * 86400000).toISOString() };
return msg;

// Renvoie les événements enregistrés vers les tableaux de bord, comme s'ils venaient de S2.
const messages = (msg.payload || []).map(l => {
    let e = {};
    try { e = JSON.parse(l.details); } catch (err) { e = { type: "inconnu" }; }
    if (!e.received_at) e.received_at = l.received_at;
    return { topic: "pce92/evenements", replay: true, payload: e };
});
node.status({ fill: "blue", shape: "dot", text: messages.length + " événement(s) rechargé(s)" });
return [messages];

// Requête « 7 derniers jours ». msg.node_id = un capteur précis, ou absent = tous les capteurs.
// msg.jours = nombre de jours (7 par défaut).
const jours = Number(msg.jours) > 0 ? Number(msg.jours) : 7;
msg.params = {
    $depuis: new Date(Date.now() - jours * 86400000).toISOString(),
    $node_id: (msg.node_id === undefined || msg.node_id === null || msg.node_id === "") ? null : Number(msg.node_id)
};
return msg;

// Au démarrage : renvoie l'historique des 7 derniers jours vers les tableaux de bord,
// sous la même forme que les mesures publiées par S2, marqué replay = true.
const lignes = msg.payload || [];
const messages = lignes.map(l => ({
    topic: "pce92/mesures/" + l.node_id,
    replay: true,
    payload: {
        node_id: l.node_id, received_at: l.received_at,
        water_mm: l.water_mm, water_valid: l.water_valid === 1,
        batt_v: l.batt_v, seq: l.seq, alert: l.alert === 1, next_min: l.next_min,
        expected_next_at: l.next_min === null ? null
            : new Date(Date.parse(l.received_at) + l.next_min * 60000).toISOString(),
        lost_before: l.lost_before, rssi: l.rssi, snr: l.snr, source: l.source, payload_hex: l.payload_hex
    }
}));
node.status({ fill: "blue", shape: "dot", text: messages.length + " mesure(s) rechargée(s)" });
return [messages];

// Prépare l'enregistrement d'une mesure (topic pce92/mesures/<node_id>, publié par S2).
const m = msg.payload;
if (!m || typeof m.node_id !== "number" || !m.received_at) {
    node.warn("Mesure ignorée : format inattendu");
    return null;
}
const b = (v) => (v ? 1 : 0);
msg.params = {
    $node_id: m.node_id,
    $received_at: new Date(m.received_at).toISOString(),   // format unique, pour trier et filtrer
    $water_mm: m.water_valid ? m.water_mm : null,
    $water_valid: b(m.water_valid),
    $batt_v: m.batt_v ?? null,
    $seq: m.seq,
    $alert: b(m.alert),
    $next_min: m.next_min ?? null,
    $lost_before: m.lost_before || 0,
    $rssi: m.rssi ?? null,
    $snr: m.snr ?? null,
    $source: m.source ?? null,
    $payload_hex: m.payload_hex ?? null
};
return msg;

// Prépare l'enregistrement d'un événement (topic pce92/evenements, publié par S2).
const e = msg.payload || {};
msg.params = {
    $received_at: new Date(e.received_at || Date.now()).toISOString(),
    $type: e.type || "inconnu",
    $node_id: e.node_id ?? null,
    $seq: e.seq ?? null,
    $details: JSON.stringify(e)
};
return msg;

// Requête « 7 derniers jours ». msg.node_id = un capteur précis, ou absent = tous les capteurs.
// msg.jours = nombre de jours (7 par défaut).
const jours = Number(msg.jours) > 0 ? Number(msg.jours) : 7;
msg.params = {
    $depuis: new Date(Date.now() - jours * 86400000).toISOString(),
    $node_id: (msg.node_id === undefined || msg.node_id === null || msg.node_id === "") ? null : Number(msg.node_id)
};
return msg;

// Résume le résultat de la requête dans le panneau debug.
const lignes = msg.payload || [];
const parCapteur = {};
for (const l of lignes) parCapteur[l.node_id] = (parCapteur[l.node_id] || 0) + 1;
node.status({ fill: "green", shape: "dot", text: lignes.length + " mesure(s) sur 7 jours" });
msg.resume = { total: lignes.length, par_capteur: parCapteur,
               premiere: lignes.length ? lignes[0].received_at : null,
               derniere: lignes.length ? lignes[lignes.length - 1].received_at : null };
return msg;

// GET /pce92/mesures?node_id=3&jours=7&format=csv
const q = msg.req.query || {};
const jours = Math.min(Math.max(Number(q.jours) || 7, 1), 366);
msg.format = q.format === "csv" ? "csv" : "json";
msg.params = {
    $depuis: new Date(Date.now() - jours * 86400000).toISOString(),
    $node_id: q.node_id ? Number(q.node_id) : null
};
return msg;

// Met en forme la réponse : JSON (par défaut) ou CSV (export, par ex. pour OPALimpact).
const lignes = (msg.payload || []).map(l => Object.assign({}, l,
    { water_valid: l.water_valid === 1, alert: l.alert === 1 }));
if (msg.format === "csv") {
    const colonnes = ["node_id", "received_at", "water_mm", "water_valid", "batt_v", "seq", "alert",
                      "next_min", "lost_before", "rssi", "snr", "source", "payload_hex"];
    const csv = [colonnes.join(",")].concat(
        lignes.map(l => colonnes.map(c => (l[c] === null || l[c] === undefined) ? "" : l[c]).join(","))
    ).join("\n");
    msg.payload = csv;
    msg.headers = { "Content-Type": "text/csv; charset=utf-8",
                    "Content-Disposition": "attachment; filename=pce92_mesures.csv" };
} else {
    msg.payload = lignes;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
}
msg.statusCode = 200;
return msg;

// AL5 / AL6 – Préparer l'affichage à partir des mesures (S2), des alertes du moteur (B2) et des événements.
// Entrées : pce92/mesures/<node_id> (S2), pce92/alertes/<node_id> (moteur d'alerte de B2,
//           plateforme/config/moteur_alerte.py), pce92/evenements (S2), et un « tic » toutes les 30 s.
// Sorties : 1. vue simple (AL5)  2. vue technique (AL6)  3. courbe du niveau  4. courbe de la batterie
// Les dates sont envoyées en ISO (UTC) et mises en forme dans le navigateur : les textes et les courbes
// affichent ainsi la même heure, celle de l'appareil qui consulte (Paris pour l'équipe, Thiès sur place).
//
// Qui décide de l'état ? Le moteur d'alerte de B2. Il lit le seuil de chaque capteur dans
// plateforme/config/seuils.csv et publie, à chaque mesure valide, un objet
// { node_id, site, etat: normal|alerte|muet, cause, hauteur_mm, seuil_mm, tendance,
//   vitesse_mm_h, temps_avant_depassement_min, received_at }.
// Les vues affichent cet état tel quel. Elles ne le recalculent que si le moteur n'a encore rien publié
// pour ce capteur (moteur arrêté) : c'est alors un calcul de secours, signalé comme tel dans la vue technique.
// Dans tous les cas, sans mesure exploitable (capteur muet ou mesure invalide), aucun verdict n'est affiché.

// --- Réglages de secours (utilisés seulement tant que le moteur n'a rien publié pour un capteur) ---
const SEUIL_SECOURS_MM = 300;    // repère de danger du contrat d'interface (bit d'alerte à 300 mm)
const AVANT_DEPASSEMENT_MAX_MIN = 120; // la vue simple n'annonce un dépassement que s'il est prévu dans les 2 h
const TENDANCE_MM = 20;          // écart minimal pour parler de hausse ou de baisse (calcul de secours)
const BATT_FAIBLE_V = 3.2;       // contrat v1.2, périmètre V2 : batterie faible sous 3,20 V
// Libellés et actions par état, à faire valider par le client.
const ETATS = {
    normal:       { libelle: "NORMAL", action: "Surveillance : aucune action." },
    alerte:       { libelle: "ALERTE", action: "Prévenir les zones à risque et se préparer à évacuer." },
    indisponible: { libelle: "DONNÉES INDISPONIBLES",
                    action: "Aucune mesure exploitable : la situation réelle est inconnue. Vérifier le capteur." }
};
const CAUSES = { seuil: "seuil dépassé", montee_rapide: "montée rapide : seuil bientôt atteint" };
const TENDANCES = { montante: "en hausse", descendante: "en baisse", stable: "stable" };
// ------------------------------------------------------------------------------------------

const etats = flow.get("etats") || {};          // dernière mesure connue par capteur
const alertes = flow.get("alertes") || {};      // dernier objet publié par le moteur, par capteur
const compteurs = flow.get("compteurs") || { perdues: 0, doublons: 0, rejets: 0, retours_seq: 0, retards: 0 };
const retards = flow.get("retards") || {};      // trames reçues en retard, par capteur (retirées des pertes)
let evenements = flow.get("evenements") || [];  // 10 derniers événements
const sorties = [null, null, null, null, null];
const FENETRE_MS = 2 * 86400000;   // mini-courbes et courbes : 48 dernières heures

// Trames perdues d'un capteur, sans celles finalement reçues en retard.
function perduesNettes(id, e) { return Math.max(0, (e.perdues || 0) - (retards[id] || 0)); }
function nomSite(id) { return (alertes[id] && alertes[id].site) || ("Capteur n° " + id); }
// Noms des courbes : fixes (le nom du site arrive avec le moteur, il ne doit pas créer une 2e courbe).
function courbe(id) { return "Niveau – nœud " + id; }
function courbeSeuil(id) { return "Seuil d'alerte – nœud " + id; }
function duree(min) {
    const m = Math.round(min);
    return m < 60 ? m + " min" : Math.floor(m / 60) + " h " + String(m % 60).padStart(2, "0");
}
function seuilConnu(id) { return alertes[id] ? alertes[id].seuil_mm : null; }

// 1. Une nouvelle mesure
if (msg.topic && msg.topic.startsWith("pce92/mesures/")) {
    const m = msg.payload;
    const e = etats[m.node_id] || { node_id: m.node_id };
    // Rechargement depuis la base (à chaque Deploy) : une mesure déjà affichée n'est pas recomptée.
    if (msg.replay && e.derniere && Date.parse(m.received_at) <= Date.parse(e.derniere.received_at)) return null;
    if (m.water_valid) {
        e.precedent_mm = e.dernier_valide ? e.dernier_valide.water_mm : null;
        e.dernier_valide = m;
    }
    e.derniere = m;
    // Heure d'arrivée dans Node-RED (sert à repérer un capteur muet). Pour l'historique
    // rechargé depuis la base (S3), on reprend l'heure de réception d'origine.
    e.arrivee = msg.replay ? Date.parse(m.received_at) : Date.now();
    etats[m.node_id] = e;
    const x = Date.parse(m.received_at);
    const niveau = [];
    const batterie = [];
    // La ligne de seuil d'abord (1re couleur : rouge). Seuil du moteur s'il est connu ; sinon le seuil
    // de secours, ou un point vide si le moteur tourne déjà (son seuil arrive juste après la mesure).
    const moteurActif = Object.keys(alertes).length > 0;
    const s = seuilConnu(m.node_id);
    niveau.push({ payload: { serie: courbeSeuil(m.node_id), x: x, y: s !== null ? s : (moteurActif ? null : SEUIL_SECOURS_MM) } });
    // Trames perdues juste avant : on coupe la courbe (point vide au milieu du trou),
    // pour ne pas tracer une ligne qui inventerait des mesures jamais reçues.
    if (m.lost_before > 0) {
        const xTrou = x - ((m.next_min || 30) * 60000) / 2;
        niveau.push({ payload: { serie: courbe(m.node_id), x: xTrou, y: null } });
        batterie.push({ payload: { serie: courbe(m.node_id).replace("Niveau", "Batterie"), x: xTrou, y: null } });
    }
    // Mesure invalide (0xFFFF) : point vide, la courbe est coupée à cet endroit.
    niveau.push({ payload: { serie: courbe(m.node_id), x: x, y: m.water_valid ? m.water_mm : null } });
    batterie.push({ payload: { serie: courbe(m.node_id).replace("Niveau", "Batterie"), x: x, y: m.batt_v } });
    // Les courbes ne montrent qu'un capteur à la fois (choisi au-dessus des courbes) : par défaut le premier reçu.
    if (flow.get("capteur_courbe") === undefined) flow.set("capteur_courbe", m.node_id);
    if (flow.get("capteur_courbe") === m.node_id) {
        sorties[2] = niveau;
        sorties[3] = batterie;
    }
    // Points des 48 dernières heures pour la mini-courbe de la tuile (null = trou).
    e.points = (e.points || []).filter(p => p.x > Date.now() - FENETRE_MS);
    if (m.lost_before > 0) e.points.push({ x: x - ((m.next_min || 30) * 60000) / 2, y: null });
    e.points.push({ x: x, y: m.water_valid ? m.water_mm : null });
    e.perdues = (e.perdues || 0) + (m.lost_before || 0);
    e.recues = (e.recues || 0) + 1;
}

// 2. Un objet d'alerte publié par le moteur de B2
if (msg.topic && msg.topic.startsWith("pce92/alertes/")) {
    const a = msg.payload || {};
    if (a.node_id !== undefined && ["normal", "alerte", "muet"].includes(a.etat)) {
        const avant = alertes[a.node_id];
        alertes[a.node_id] = a;
        // Seuil reçu pour la 1re fois, ou modifié dans seuils.csv : on place le point sur la ligne de seuil.
        // (Seulement si ce capteur a déjà des mesures affichées : au démarrage, les alertes mémorisées par MQTT
        //  arrivent avant l'historique, et ne doivent pas prendre les premières couleurs de la courbe.)
        if (a.received_at && etats[a.node_id] && flow.get("capteur_courbe") === a.node_id && (!avant || avant.seuil_mm !== a.seuil_mm)) {
            sorties[2] = [{ payload: { serie: courbeSeuil(a.node_id), x: Date.parse(a.received_at), y: a.seuil_mm } }];
        }
    } else {
        node.warn("Objet d'alerte ignoré (etat inconnu) : " + JSON.stringify(a));
    }
}

// 3. Un événement (rejet, doublon, trames perdues, retour de seq)
if (msg.topic === "pce92/evenements") {
    const ev = msg.payload;
    // Rechargement depuis la base (à chaque Deploy) : un événement déjà compté ne l'est pas deux fois.
    const evtsVus = flow.get("evts_vus") || [];
    const cleEvt = [ev.type, ev.node_id, ev.seq, ev.received_at].join("|");
    if (evtsVus.includes(cleEvt)) return null;
    evtsVus.push(cleEvt);
    flow.set("evts_vus", evtsVus.slice(-1000));
    if (ev.type === "doublon") compteurs.doublons += 1;
    if (ev.type === "rejet") compteurs.rejets += 1;
    if (ev.type === "retour_seq") compteurs.retours_seq += 1;
    if (ev.type === "trame_en_retard") {
        compteurs.retards = (compteurs.retards || 0) + 1;
        retards[ev.node_id] = (retards[ev.node_id] || 0) + 1;
    }
    const textes = {
        trames_perdues: (ev.nombre + " trame(s) perdue(s) avant la seq " + ev.seq),
        doublon: (ev.en_retard ? "doublon arrivé en retard, écarté (seq " + ev.seq + ", " + ev.retard_trames + " trame(s) de retard)"
                               : "doublon écarté (seq " + ev.seq + ")"),
        trame_en_retard: ("trame perdue finalement reçue en retard (seq " + ev.seq + ") : gardée dans l'historique, pas affichée comme mesure actuelle"),
        rejet: ("trame rejetée : " + ev.raison),
        retour_seq: ("compteur revenu en arrière (" + ev.seq_precedent + " → " + ev.seq + ")")
    };
    evenements.unshift({ heure_iso: ev.received_at || new Date().toISOString(),
                         capteur: ev.node_id ?? "—", texte: textes[ev.type] || ev.type });
    evenements = evenements.slice(0, 10);
}

flow.set("etats", etats);
flow.set("alertes", alertes);
flow.set("compteurs", compteurs);
flow.set("retards", retards);
flow.set("evenements", evenements);

// 4. Recalculer les deux vues (à chaque message, y compris le tic de 30 s)
const sites = [], lignes = [];
let derniereReception = null;
for (const id of Object.keys(etats).sort((a, b) => a - b)) {
    const e = etats[id];
    const d = e.derniere;
    const v = e.dernier_valide;
    const a = alertes[id];
    const periode = d.next_min || 60;
    // Capteur muet : aucune nouvelle trame depuis 2 × next_min + 5 min (même délai que le moteur
    // d'alerte de B2) : une trame perdue est tolérée, deux ne le sont pas.
    const delaiMuetMin = 2 * periode + 5;
    const muet = Date.now() > (e.arrivee || Date.parse(d.received_at)) + delaiMuetMin * 60000
                 || (a && a.etat === "muet");

    // État : celui du moteur s'il a publié pour ce capteur, sinon calcul de secours sur le seuil de secours.
    let etat, source, cause = null, tendance = "", vitesse = null, avantDepassement = null, seuil;
    if (a) {
        etat = a.etat === "alerte" ? "alerte" : "normal";
        cause = a.cause;
        seuil = a.seuil_mm;
        tendance = TENDANCES[a.tendance] || "";
        vitesse = a.vitesse_mm_h;
        avantDepassement = a.temps_avant_depassement_min;
        // Le moteur n'a pas encore répondu à la dernière mesure valide (normal pendant une fraction de seconde ;
        // s'il dure, le moteur est sans doute arrêté) : on le signale dans la vue technique.
        const enRetard = v && a.received_at !== v.received_at && Date.now() - e.arrivee > 10000;
        source = enRetard ? "moteur d'alerte (n'a pas répondu à la dernière mesure)" : "moteur d'alerte";
    } else {
        seuil = SEUIL_SECOURS_MM;
        etat = (v && v.water_mm >= seuil) || d.alert ? "alerte" : "normal";  // règle 3 : le bit d'alerte compte
        if (etat === "alerte") cause = "seuil";
        if (v && e.precedent_mm !== null && e.precedent_mm !== undefined) {
            const diff = v.water_mm - e.precedent_mm;
            tendance = diff >= TENDANCE_MM ? "en hausse" : (diff <= -TENDANCE_MM ? "en baisse" : "stable");
        }
        source = "calcul de secours (moteur absent)";
    }
    // Sans mesure exploitable, pas de verdict : jamais de NORMAL pour un capteur muet.
    const sansVerdict = muet || !d.water_valid;
    if (sansVerdict) { etat = "indisponible"; cause = null; tendance = ""; avantDepassement = null; }

    let precision = "";
    if (etat === "alerte" && CAUSES[cause]) precision = CAUSES[cause];
    // Niveau repassé sous le seuil mais alerte maintenue par le moteur (marge de retour, pour ne pas clignoter).
    if (etat === "alerte" && cause === "seuil" && v && seuil && v.water_mm < seuil)
        precision = "niveau juste sous le seuil : alerte maintenue jusqu'à une vraie baisse";
    // Vue simple : on n'annonce le dépassement que s'il est proche (moins de 2 h), sinon le chiffre n'a pas de sens.
    if (etat === "normal" && avantDepassement !== null && avantDepassement !== undefined && avantDepassement <= AVANT_DEPASSEMENT_MAX_MIN)
        precision = "seuil atteint dans " + duree(avantDepassement) + " environ, au rythme actuel";

    sites.push({
        node_id: Number(id), nom: nomSite(id), etat: etat,
        libelle: ETATS[etat].libelle, action: ETATS[etat].action, precision: precision,
        niveau: v ? Math.round(v.water_mm / 10) + " cm" : "—",
        seuil: seuil !== null && seuil !== undefined ? Math.round(seuil / 10) + " cm" : "—",
        ancien: sansVerdict ? (v ? "Dernier niveau connu : " + Math.round(v.water_mm / 10) + " cm" : "Aucun niveau connu") : "",
        ancien_iso: sansVerdict && v ? v.received_at : null,
        tendance: tendance,
        derniere_iso: d.received_at
    });
    // Gravité, pour trier : 0 alerte, 1 données indisponibles, 2 dépassement proche, 3 normal.
    const rang = etat === "alerte" ? 0 : (etat === "indisponible" ? 1 : (precision ? 2 : 3));
    sites[sites.length - 1].rang = rang;
    lignes.push({
        node_id: Number(id), nom: nomSite(id), rang: rang, cle_etat: etat, precision: precision,
        niveau_mm: v ? v.water_mm : null, seuil_mm: seuil ?? null,
        points: (e.points || []).filter(p => p.x > Date.now() - FENETRE_MS), etat: ETATS[etat].libelle + (etat === "alerte" && cause ? " (" + cause + ")" : ""),
        source: sansVerdict ? "—" : source,
        reception: muet ? "en retard" : (d.water_valid ? "à jour" : "mesure invalide"),
        derniere_iso: d.received_at,
        prochaine_iso: d.expected_next_at,
        niveau: d.water_valid ? d.water_mm + " mm" : "invalide",
        seuil: seuil !== null && seuil !== undefined ? seuil + " mm" : "—",
        tendance: sansVerdict ? "—" : (tendance || "—") + (vitesse !== null && vitesse !== undefined ? " (" + vitesse + " mm/h)" : ""),
        depassement: sansVerdict || avantDepassement === null || avantDepassement === undefined ? "—" : duree(avantDepassement),
        bit: d.alert ? "levé" : "non",
        batterie: d.batt_v === null ? "inconnue" : d.batt_v.toFixed(2) + " V" + (d.batt_v < BATT_FAIBLE_V ? " (faible)" : ""),
        batt_faible: d.batt_v !== null && d.batt_v < BATT_FAIBLE_V,
        signal: (d.rssi ?? "—") + " dBm / " + (d.snr ?? "—") + " dB",
        seq: d.seq,
        perdues: perduesNettes(id, e),
        taux: e.recues ? Math.round(100 * (e.recues + (retards[id] || 0)) / (e.recues + (retards[id] || 0) + perduesNettes(id, e))) + " %" : "—"
    });
    if (!derniereReception || d.received_at > derniereReception) derniereReception = d.received_at;
}

// Tri par gravité (le plus urgent en haut), puis par numéro de capteur.
const parGravite = (a, b) => (a.rang - b.rang) || (a.node_id - b.node_id);
sites.sort(parGravite);
lignes.sort(parGravite);

// Capteur affiché dans les grandes courbes : celui choisi par un clic (capteur_manuel) ; sans clic, le plus
// critique. Pas pendant le rechargement de l'historique.
// Un capteur qui ENTRE en alerte remplace le choix de l'expert : la courbe bascule sur ce capteur.
const enAlerte = lignes.filter(l => l.rang === 0).map(l => l.node_id);
const avantAlerte = flow.get("ids_en_alerte") || [];
const nouvelle = enAlerte.find(id => !avantAlerte.includes(id));
if (!msg.replay && nouvelle !== undefined) flow.set("capteur_manuel", nouvelle);
flow.set("ids_en_alerte", enAlerte);
if (!msg.replay && lignes.length) {
    const manuel = lignes.find(l => l.node_id === flow.get("capteur_manuel"));
    const voulu = manuel ? manuel.node_id : lignes[0].node_id;
    if (voulu !== flow.get("capteur_courbe")) sorties[4] = { payload: { node_id: voulu, auto: true } };
}

// Total des trames perdues = somme par capteur (recalculée aussi après un redémarrage, grâce à S3).
compteurs.perdues = Object.keys(etats).reduce((t, id) => t + perduesNettes(id, etats[id]), 0);
sorties[0] = { payload: { sites: sites } };
sorties[1] = { payload: {
    capteurs: lignes, compteurs: compteurs, evenements: evenements,
    derniere_reception_iso: derniereReception, capteur_courbe: flow.get("capteur_courbe") ?? null
} };
return sorties;

// Efface l'état mémorisé et vide les deux courbes (utile avant une démonstration).
flow.set("etats", {});
flow.set("alertes", {});
flow.set("compteurs", { perdues: 0, doublons: 0, rejets: 0, retours_seq: 0, retards: 0 });
flow.set("retards", {});
flow.set("evts_vus", []);
flow.set("evenements", []);
flow.set("capteur_courbe", undefined);
flow.set("capteur_manuel", undefined);
flow.set("ids_en_alerte", []);
node.status({ fill: "blue", shape: "dot", text: "réinitialisé à " + new Date().toLocaleTimeString("fr-FR") });
return [{ payload: [] }, { topic: "tic" }];

// Vue technique – changer le capteur des grandes courbes : clic sur une tuile (choix de l'expert, mémorisé)
// ou bascule automatique vers le capteur le plus critique. On relit ses 48 dernières heures dans la base (S3).
const id = Number(msg.payload && msg.payload.node_id);
if (!Number.isFinite(id)) return null;
if (!msg.payload.auto) flow.set("capteur_manuel", id);
flow.set("capteur_courbe", id);
msg.node_id = id;
msg.params = { $node_id: id, $depuis: new Date(Date.now() - 2 * 86400000).toISOString() };
return msg;

// Vue technique – reconstruire les deux courbes (niveau, batterie) pour le capteur choisi, à partir de la base.
// Sorties : 1. courbe du niveau  2. courbe de la batterie  3. recalcul des vues (pour mettre à jour le choix)
const lignes = msg.payload || [];
const id = msg.node_id;
const a = (flow.get("alertes") || {})[id];
const seuil = a ? a.seuil_mm : 300;
const serieSeuil = "Seuil d'alerte – nœud " + id, serieNiveau = "Niveau – nœud " + id, serieBatt = "Batterie – nœud " + id;
const seuils = [], niveau = [], batterie = [];
let precedent = null;
for (const l of lignes) {
    const x = Date.parse(l.received_at);
    // Mêmes règles que la vue en direct : courbe coupée avant des trames perdues et sur une mesure invalide ;
    // en plus ici, coupée si le capteur est resté muet plus de 2 × next_min + 5 min.
    const trou = l.lost_before > 0 || (precedent !== null && x - precedent > (2 * (l.next_min || 30) + 5) * 60000);
    if (trou && precedent !== null) {
        const xt = Math.round((precedent + x) / 2);
        niveau.push({ serie: serieNiveau, x: xt, y: null });
        batterie.push({ serie: serieBatt, x: xt, y: null });
    }
    seuils.push({ serie: serieSeuil, x: x, y: seuil });
    niveau.push({ serie: serieNiveau, x: x, y: l.water_valid === 1 ? l.water_mm : null });
    batterie.push({ serie: serieBatt, x: x, y: l.batt_v });
    precedent = x;
}
return [
    { action: "replace", payload: lignes.length ? seuils.concat(niveau) : [] },
    { action: "replace", payload: lignes.length ? batterie : [] },
    { topic: "tic" }
];

// Historique – choisir la requête selon la demande de la page (liste des capteurs ou période d'un capteur).
const d = msg.payload || {};
if (d.action === "liste") return [msg, null];
if (d.action === "afficher") {
    const jours = [1, 2, 7, 30].includes(Number(d.jours)) ? Number(d.jours) : 2;
    msg.node_id = Number(d.node_id);
    msg.jours = jours;
    msg.depuis_iso = new Date(Date.now() - jours * 86400000).toISOString();
    msg.params = { $depuis: msg.depuis_iso, $node_id: msg.node_id };
    return [null, msg];
}
return null;

// Historique – liste des capteurs présents dans la base, avec le nom du site donné par le moteur (seuils.csv).
const alertes = flow.get("alertes") || {};
const capteurs = (msg.payload || []).map(l => ({
    node_id: l.node_id,
    nom: (alertes[l.node_id] && alertes[l.node_id].site ? alertes[l.node_id].site + " (nœud " + l.node_id + ")" : "Capteur n° " + l.node_id)
}));
return { payload: { capteurs: capteurs } };

// Garde les mesures lues, puis passe à la lecture des événements de la même période.
msg.mesures = msg.payload || [];
return msg;

// Historique – préparer la courbe et le résumé de la période choisie.
// Sorties : 1. courbe (remplace tout le contenu)  2. résumé
const lignes = msg.mesures || [];
const evts = msg.payload || [];
const id = msg.node_id;
const a = (flow.get("alertes") || {})[id];
const seuil = a ? a.seuil_mm : 300;
const seuilSource = a ? "seuils.csv, via le moteur d'alerte" : "seuil de secours (le moteur n'a pas encore publié pour ce capteur)";
const nom = a && a.site ? a.site + " (nœud " + id + ")" : "Capteur n° " + id;

// Courbe : la ligne de seuil d'abord (1re couleur : rouge), puis le niveau.
// On coupe la courbe (point vide) : avant des trames perdues, sur une mesure invalide,
// et quand le capteur est resté muet plus de 2 × next_min + 5 min.
const points = [];
const niveau = [];
let precedent = null;
for (const l of lignes) {
    const x = Date.parse(l.received_at);
    const periode = l.next_min || 30;
    const trou = l.lost_before > 0 || (precedent !== null && x - precedent > (2 * periode + 5) * 60000);
    if (trou && precedent !== null) niveau.push({ serie: "Niveau", x: Math.round((precedent + x) / 2), y: null });
    niveau.push({ serie: "Niveau", x: x, y: l.water_valid === 1 ? l.water_mm : null });
    precedent = x;
}
if (lignes.length) {
    const debut = Date.parse(lignes[0].received_at), fin = Date.parse(lignes[lignes.length - 1].received_at);
    points.push({ serie: "Seuil d'alerte actuel (" + seuil + " mm)", x: debut, y: seuil },
                { serie: "Seuil d'alerte actuel (" + seuil + " mm)", x: fin, y: seuil });
}
const courbe = { action: "replace", payload: points.concat(niveau) };
if (!lignes.length) courbe.payload = [];

// Résumé
const valides = lignes.filter(l => l.water_valid === 1);
// Les trames perdues puis reçues en retard (événement trame_en_retard) ne comptent plus comme perdues.
const enRetard = evts.filter(l => l.type === "trame_en_retard").length;
const perdues = Math.max(0, lignes.reduce((t, l) => t + (l.lost_before || 0), 0) - enRetard);
let max = null;
for (const l of valides) if (!max || l.water_mm > max.water_mm) max = l;
const textes = {
    trames_perdues: e => e.nombre + " trame(s) perdue(s) avant la seq " + e.seq,
    doublon: e => e.en_retard ? "doublon arrivé en retard, écarté (seq " + e.seq + ")" : "doublon écarté (seq " + e.seq + ")",
    trame_en_retard: e => "trame perdue finalement reçue en retard (seq " + e.seq + ", " + (e.water_valid ? e.water_mm + " mm" : "mesure invalide")
                        + ", mesurée vers " + new Date(e.mesure_estimee_a).toLocaleString("fr-FR", { timeZone: "Europe/Paris" }) + ")",
    retour_seq: e => "compteur revenu en arrière (" + e.seq_precedent + " → " + e.seq + ")",
    rejet: e => "trame rejetée : " + e.raison
};
const evenements = evts.map(l => {
    let e = {};
    try { e = JSON.parse(l.details); } catch (err) { e = { type: l.type }; }
    return { heure_iso: l.received_at, texte: textes[l.type] ? textes[l.type](e) : l.type };
});
const resume = { payload: {
    node_id: id, nom: nom, depuis_iso: msg.depuis_iso, jusqua_iso: new Date().toISOString(),
    mesures: lignes.length, perdues: perdues,
    taux: lignes.length ? Math.round(100 * (lignes.length + enRetard) / (lignes.length + enRetard + perdues)) + " %" : "—",
    invalides: lignes.length - valides.length,
    max_mm: max ? max.water_mm + " mm" : "—", max_iso: max ? max.received_at : null,
    seuil_mm: seuil, seuil_source: seuilSource,
    au_dessus: valides.filter(l => l.water_mm >= seuil).length,
    premiere_iso: lignes.length ? lignes[0].received_at : null,
    derniere_iso: lignes.length ? lignes[lignes.length - 1].received_at : null,
    evenements: evenements
} };
node.status({ fill: "blue", shape: "dot", text: nom + " · " + msg.jours + " j · " + lignes.length + " mesure(s)" });
return [courbe, resume];
